import gurobipy as gp
from gurobipy import GRB

def solve_problem():
    suppliers = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'S7', 'S8', 'S9', 'S10', 'S11', 'S12']
    customers = ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10', 'C11', 'C12']
    demand = {'C1': 52, 'C2': 80, 'C3': 392, 'C4': 103, 'C5': 32, 'C6': 1426, 'C7': 1024, 'C8': 2736, 'C9': 1129, 'C10': 676, 'C11': 2631, 'C12': 31}
    supply_capacity = {'S1': 58, 'S2': 32, 'S3': 6161, 'S4': 4, 'S5': 47, 'S6': 178, 'S7': 142, 'S8': 164, 'S9': 1011, 'S10': 6, 'S11': 7081, 'S12': 948}
    cost = {'S1': {'C1': 134.72882437877243, 'C2': 72.30045141110347, 'C3': 37.9759927355347, 'C4': 61.546392323, 'C5': 1650.3353902326157, 'C6': 162.685676173, 'C7': 140.104504471, 'C8': 611.84656497826, 'C9': 84.1938756682, 'C10': 198.836206966, 'C11': 1538.830198350349, 'C12': 2320.1146477101956}, 'S2': {'C1': 23.835369186583733, 'C2': 1128.6332865368709, 'C3': 187.05459590556023, 'C4': 1.6077337129635412, 'C5': 2227.7036991312493, 'C6': 72.44693148708649, 'C7': 27.6251928873, 'C8': 1413.10777115, 'C9': 1142.96692928, 'C10': 436.407095355, 'C11': 1702.1724763823142, 'C12': 1925.8446970545492}, 'S3': {'C1': 1138.498759622659, 'C2': 231.8983422482863, 'C3': 44.1568226726957, 'C4': 146.558261391, 'C5': 217.288746687, 'C6': 956.655534239, 'C7': 1133.3755152, 'C8': 33.3404508802, 'C9': 136.70204401709762, 'C10': 1055.98688761, 'C11': 627.787358831, 'C12': 36.70238978444623}, 'S4': {'C1': 1043.7562803117191, 'C2': 24.207016063238527, 'C3': 1120.9890438994094, 'C4': 482.494343073, 'C5': 893.4457577903337, 'C6': 1041.17824487, 'C7': 862.247063166, 'C8': 354.919284956, 'C9': 1041.17824487, 'C10': 815.540743544, 'C11': 744.974841115, 'C12': 437.9556823253786}, 'S5': {'C1': 4.939930661779214, 'C2': 1278.1815735383598, 'C3': 549.7570743190075, 'C4': 77.3788569216, 'C5': 98.32689279702352, 'C6': 0.00116194410309, 'C7': 4.50867471501, 'C8': 1936.8981353, 'C9': 0.001236242263106387, 'C10': 0.000989364683164, 'C11': 1921.27577674, 'C12': 1619.6154655942953}, 'S6': {'C1': 2105.5398596409113, 'C2': 1340.9770559580859, 'C3': 2077.2747284488696, 'C4': 1141.71011597, 'C5': 1223.50746586, 'C6': 85.5636653585, 'C7': 1850.55898264, 'C8': 683.989734378, 'C9': 2393.213466538681, 'C10': 118.634912242, 'C11': 836.796875718, 'C12': 818.9532260267922}, 'S7': {'C1': 61.36183063260923, 'C2': 113.23716964851326, 'C3': 50.231076475261865, 'C4': 177.581500998, 'C5': 108.97945207, 'C6': 1489.31558034, 'C7': 68.5166200844, 'C8': 552.113112102, 'C9': 957.3213131437595, 'C10': 1196.742234, 'C11': 463.863490513, 'C12': 483.3345987058458}, 'S8': {'C1': 1169.3640988900754, 'C2': 1037.2170744709088, 'C3': 732.3577706907058, 'C4': 757.527693473, 'C5': 1510.0296187049466, 'C6': 780.853789775776, 'C7': 1129.60571953, 'C8': 1594.63250105, 'C9': 61.82504909829045, 'C10': 58.3257513193, 'C11': 77.9079144678, 'C12': 1479.1137195486635}, 'S9': {'C1': 7.936521667214095, 'C2': 1357.5387610434743, 'C3': 628.3001825422914, 'C4': 1662.55696566, 'C5': 1346.13543545, 'C6': 1760.0085249934855, 'C7': 8.84842800678, 'C8': 1249.6023209, 'C9': 1523.90479124, 'C10': 91.0073344573, 'C11': 1379.65787593, 'C12': 1423.5615412405277}, 'S10': {'C1': 1685.3409758586952, 'C2': 437.39384912973503, 'C3': 1568.8939936485654, 'C4': 429.294193689, 'C5': 498.37544466423503, 'C6': 1444.70868586, 'C7': 1900.22195028, 'C8': 207.875970859, 'C9': 1527.6606596831157, 'C10': 1243.21024485, 'C11': 2.20108252307, 'C12': 45.95308313010429}, 'S11': {'C1': 937.1094078301182, 'C2': 903.0141415848653, 'C3': 264.7208998642393, 'C4': 862.748055895, 'C5': 1661.105486348982, 'C6': 36.8270942987, 'C7': 1031.28890332, 'C8': 1846.29100627, 'C9': 907.425738541, 'C10': 48.4219217044, 'C11': 1510.07246191, 'C12': 1574.7961500081667}, 'S12': {'C1': 1685.7576850724427, 'C2': 377.3256672852414, 'C3': 1347.0162725120726, 'C4': 605.20950386, 'C5': 23.612177980608287, 'C6': 83.08521829288628, 'C7': 1965.42488503, 'C8': 11.7746976137, 'C9': 1854.69288714, 'C10': 1965.94236917, 'C11': 0.0112202532761, 'C12': 963.9941814871104}}
    for i in suppliers:
        if i not in cost:
            raise ValueError(f'Missing cost data for supplier {i}')
        for j in customers:
            if j not in cost[i]:
                raise ValueError(f'Missing cost data for supplier {i}, customer {j}')
    for j in customers:
        if j not in demand:
            raise ValueError(f'Missing demand data for customer {j}')
    for i in suppliers:
        if i not in supply_capacity:
            raise ValueError(f'Missing supply capacity data for supplier {i}')
    m = gp.Model('Retail_Supply_Chain')
    x = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
    m.setObjective(gp.quicksum((cost[i][j] * x[i, j] for i in suppliers for j in customers)), GRB.MINIMIZE)
    m.addConstrs((gp.quicksum((x[i, j] for i in suppliers)) >= demand[j] for j in customers), name='')
    m.addConstrs((gp.quicksum((x[i, j] for j in customers)) <= supply_capacity[i] for i in suppliers), name='')
    m.Params.MIPGap = 0.0001
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(f'ObjVal: {m.ObjVal}')
        for var in m.getVars():
            print(f'{var.VarName}: {var.X}')
    else:
        print(f'Solver status: {m.Status}')
    return m
m = solve_problem()